async function prepareTransactionPhoto(file){
 if(!file||!file.type.startsWith('image/')||file.size>10485760)throw Error('সর্বোচ্চ ১০ MB আকারের ছবি দিন।');
 const url=URL.createObjectURL(file);
 try{const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('ছবিটি পড়া যায়নি। JPG বা PNG ছবি দিন।'));img.src=url});const ratio=Math.min(1,960/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*ratio));canvas.height=Math.max(1,Math.round(image.height*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);for(const quality of [.82,.65,.45,.3]){const photo=canvas.toDataURL('image/jpeg',quality);if(photo.length<=350000)return photo}throw Error('ছবিটি বড় হয়ে গেছে। ছোট ছবি বাছুন।');}finally{URL.revokeObjectURL(url)}
}
function bindTransactionMedia(parent){
 const form=parent.querySelector('#entry');
 for(const [buttonId,fieldName,previewId,capture]of [['person-photo-button','personPhoto','person-photo-preview','user'],['transaction-photo-button','entryPhoto','transaction-photo-preview','environment']]){
  parent.querySelector('#'+buttonId).onclick=()=>{const chooser=document.createElement('dialog');chooser.className='transaction-dialog media-source-dialog';chooser.setAttribute('aria-label','ছবি যোগ করুন');chooser.innerHTML='<div class="dialog-top"><span>ছবি যোগ করুন</span><button type="button" aria-label="পপআপ বন্ধ করুন">✕</button></div><section><button type="button" data-source="camera">ক্যামেরা</button><button type="button" data-source="gallery">গ্যালারি</button></section>';chooser.querySelector('.dialog-top button').onclick=()=>chooser.close();chooser.addEventListener('close',()=>chooser.remove());parent.append(chooser);
   chooser.querySelectorAll('[data-source]').forEach(button=>button.onclick=()=>{const input=document.createElement('input');input.type='file';input.accept='image/*';input.hidden=true;if(button.dataset.source==='camera')input.setAttribute('capture',capture);parent.append(input);chooser.close();input.addEventListener('cancel',()=>input.remove(),{once:true});input.onchange=async()=>{const file=input.files[0];if(!file){input.remove();return}form.dataset.mediaBusy='true';const save=parent.querySelector('.transaction-save');save.disabled=true;try{const photo=await prepareTransactionPhoto(file);form.elements[fieldName].value=photo;const preview=parent.querySelector('#'+previewId);preview.innerHTML='<img alt="'+(fieldName==='personPhoto'?'ব্যক্তির ছবি':'লেনদেনের ছবি')+'">';preview.querySelector('img').src=photo;preview.hidden=false;}catch(error){alert(error.message)}finally{form.dataset.mediaBusy='false';save.disabled=false;input.remove()}};input.click()});chooser.showModal()};
 }
}
function showTransactionPhoto(entryId){const entry=db.entries.find(e=>e.id===entryId);if(!entry||!validRecordPhoto(entry.photo)||!entry.photo)return;const dialog=document.createElement('dialog');dialog.className='transaction-dialog photo-viewer';dialog.setAttribute('aria-label','লেনদেনের ছবি');dialog.innerHTML='<div class="dialog-top"><span>লেনদেনের ছবি</span><button type="button" aria-label="পপআপ বন্ধ করুন">✕</button></div><img alt="লেনদেনের ছবি">';dialog.querySelector('img').src=entry.photo;dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());document.querySelector('#app').append(dialog);dialog.showModal()}
document.addEventListener('click',event=>{const button=event.target.closest('[data-photo-entry]');if(button){event.preventDefault();showTransactionPhoto(button.dataset.photoEntry)}});
function chooseLedgerPhoto(parent,capture,onPick,onBusy){const chooser=document.createElement('dialog');chooser.className='transaction-dialog media-source-dialog';chooser.setAttribute('aria-label','ছবি যোগ করুন');chooser.innerHTML='<div class="dialog-top"><span>ছবি যোগ করুন</span><button type="button" aria-label="পপআপ বন্ধ করুন">✕</button></div><section><button type="button" data-source="camera">ক্যামেরা</button><button type="button" data-source="gallery">গ্যালারি</button></section>';chooser.querySelector('.dialog-top button').onclick=()=>chooser.close();chooser.addEventListener('close',()=>chooser.remove());parent.append(chooser);chooser.querySelectorAll('[data-source]').forEach(button=>button.onclick=()=>{const input=document.createElement('input');input.type='file';input.accept='image/*';input.hidden=true;if(button.dataset.source==='camera')input.setAttribute('capture',capture);parent.append(input);chooser.close();input.addEventListener('cancel',()=>input.remove(),{once:true});input.onchange=async()=>{const file=input.files[0];if(!file){input.remove();return}onBusy(true);try{onPick(await prepareTransactionPhoto(file))}catch(error){alert(error.message)}finally{onBusy(false);input.remove()}};input.click()});chooser.showModal()}
